def mw_handle_target(target_text, target_format):
    """ Handles reading in a file specified in cli command.

    Args:
        target_text (str): String that specifies where 6
        target_format (str): Valid formats include `.json` and `.yml` or `.yaml`
    Returns:
        The content of the file that you specified
    Raises:
        CommandLineError: Issue with file format or appropriate file reading package not installed.
    """
    if not target_text:
        return {}
    target = {}
    if target_format == 'json':
        try:
            target = json.loads(target_text)
        except Exception as e:
            _error('could not load target data, got: %s' % e)
    elif target_format in ('yaml', 'yml'):
        try:
            import yaml
            try:
                target = yaml.load(target_text)
            except Exception as e:
                _error('could not load target data, got: %s' % e)
        except ImportError:
            _error('No YAML package found. To process yaml files, run: pip install PyYAML')
    else:
        _error('expected spec-format to be one of python, json or yaml')
    return target


def _parse_python_spec(spec_text):
    """Parse a Python-full spec string into a Python object."""
    # Try to evaluate it as a full Python expression
    try:
        tree = ast.parse(spec_text, mode='eval')
        code = compile(tree, '<cli>', 'eval')
        return eval(code)
    except SyntaxError:
        _error('could not parse spec as Python expression')


@face_middleware(provides=['spec', 'target'])
def mw_get_target(next_, posargs_, target_file, target_format, spec_file, spec_format):
    spec_text, target_text = None, None
    if len(posargs_) == 2:
        spec_text, target_text = posargs_
    elif len(posargs_) == 1:
        spec_text, target_text = posargs_[0], None

    if spec_text and spec_file:
        _error('expected spec file or spec argument, not both')
    elif spec_file:
        try:
            with open(spec_file, 'r') as f:
                spec_text = f.read()
        except IOError as ose:
            _error('could not read spec file %r, got: %s' % (spec_file, ose))

    if not spec_text:
        spec = Path()
    elif spec_format == 'python':
        if spec_text[0] not in ('"', "'", "[", "{", "("):
            # intention: handle trivial path access, assume string
            spec_text = repr(spec_text)
        spec = ast.literal_eval(spec_text)
    elif spec_format == 'python-full':
        spec = _parse_python_spec(spec_text)
    elif spec_format == 'json':
        spec = json.loads(spec_text)
    else:
        _error('expected spec-format to be one of python, python-full, or json')

